use nepl3_core::value_codec::FoundationValueCodec;
use nepl3_doc_core::{check::Category,lower,model::*,portable,prepare::{self,DocRequirement,PreparationError}};
const INPUT:&str="article ja \"独立\"\r\nbody cons code Math root 0 9 cons paragraph cons sentence cons link page \"未配置\" some \"先\" text \"参照\" cons math Math frac 2 0 cons image asset \"missing.svg\" none \"代替\" nil nil nil";
fn unique_bytes(doc:&DocumentSyntax)->u64{let mut all=doc.sources.iter().collect::<Vec<_>>();for e in &doc.value.embeds{all.extend(e.closure.owner_sources.iter());all.extend(e.closure.syntax.bundle.sources.iter());}let mut identities=Vec::new();let mut total=0;for source in all{if !identities.contains(source.identity()){identities.push(source.identity().clone());total+=source.text().len() as u64;}}total}
fn main()->Result<(),String>{let compiled=compiled()?;with_input(&compiled,INPUT,"Article",|tree,profile,b,a|{
 let before=tree.tree().clone();let checked=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;let empty=SourceStore::default();let mut aa=SourceAdmission::default();let mut cc=FoundationCodec::new(profile.registry(),&empty,&mut aa).map_err(err)?;
 let doc=lower::document(&checked,&compiled.doc.package.schema,Category::Article,profile.registry(),&mut budget(),&mut cc).map_err(err)?;let unchanged=doc.clone();assert_eq!(tree.tree(),&before);
 let mut admission=SourceAdmission::default();let mut codec=FoundationCodec::new(profile.registry(),&empty,&mut admission).map_err(err)?;let mut operation=budget();let plan=prepare::inspect(&doc,profile.registry(),&mut codec,&mut operation).map_err(err)?;assert_eq!(operation.usage().source_bytes,unique_bytes(&doc));assert_eq!(plan.requirements.len(),4);
 let DocRequirement::Link{node,target:LinkTarget::Page{page,fragment}}=&plan.requirements[0] else{return Err("link first".into())};assert_eq!(page,"未配置");assert_eq!(fragment.as_deref(),Some("先"));let link=&doc.value.nodes[*node as usize];assert!(matches!(link.kind,DocKind::Link{..}));let span=link.span.as_ref().ok_or("link cover")?;assert_eq!(&INPUT[span.start() as usize..span.start() as usize+4],"link");
 assert!(matches!(&plan.requirements[1],DocRequirement::Asset{asset,..} if asset.id=="missing.svg"&&asset.digest.is_none()));
 for(index,kind)in [EmbedKind::Code,EmbedKind::InlineMath].into_iter().enumerate(){let guest=&doc.value.embeds[index];let raw=codec.encode_foreign_closure(&guest.closure,&mut budget()).map_err(err)?;let mut input=b"NEPL3.Doc.Prepare.Guest.v1\0".to_vec();input.extend(nepl3_wire::encode(&raw,&mut budget()).map_err(err)?);assert_eq!(plan.requirements[2+index],DocRequirement::Foreign{embed:EmbedRef(index as u64),kind,guest_digest:Digest::of(&input)});}
 let root_guest=&doc.value.embeds[0].closure.syntax.bundle;assert_eq!(root_guest.nodes[root_guest.root.0 as usize].kind,"Form:Root");let frac_guest=&doc.value.embeds[1].closure.syntax.bundle;assert_eq!(frac_guest.nodes[frac_guest.root.0 as usize].kind,"Form:Frac");
 let document_raw=portable::to_value(&doc,profile.registry(),&mut codec,&mut budget()).map_err(err)?;let document_bytes=nepl3_wire::encode(&document_raw,&mut budget()).map_err(err)?;let mut digest=b"NEPL3.Doc.Prepare.Document.v1\0".to_vec();digest.extend(&document_bytes);assert_eq!(plan.document_digest,Digest::of(&digest));
 let plan_raw=portable::prepare::plan_to_value(&plan,&doc,profile.registry(),&mut codec,&mut budget()).map_err(err)?;let plan_bytes=nepl3_wire::encode(&plan_raw,&mut budget()).map_err(err)?;
 let mut fresh_admission=SourceAdmission::default();let mut fresh=FoundationCodec::new(profile.registry(),&empty,&mut fresh_admission).map_err(err)?;let mut receiving=budget();let received=portable::from_value(&nepl3_wire::decode(&document_bytes,&mut budget()).map_err(err)?,profile.registry(),&mut fresh,&mut receiving).map_err(err)?;
 let decoded=nepl3_wire::decode(&plan_bytes,&mut budget()).map_err(err)?;assert_eq!(portable::prepare::plan_from_value(&decoded,&received,profile.registry(),&mut fresh,&mut receiving).map_err(err)?,plan);assert_eq!(receiving.usage().source_bytes,unique_bytes(&doc));assert_eq!(received.value.nodes,doc.value.nodes);assert_eq!(received.origins,doc.origins);assert_eq!(received.views,doc.views);assert_eq!(nepl3_wire::encode(&portable::to_value(&received,profile.registry(),&mut fresh,&mut budget()).map_err(err)?,&mut budget()).map_err(err)?,document_bytes);
 for mutation in 0..3{let mut raw=plan_raw.clone();let NdfValue::Record(record)=&mut raw else{panic!()};let digest=record.fields[0].clone();let NdfValue::List(req)=&mut record.fields[1] else{panic!()};if mutation==0{req.remove(2);}else{let NdfValue::Variant(f)=&mut req[2] else{panic!()};if mutation==1{f.fields[2]=digest;}else{let NdfValue::Record(id)=&mut f.fields[0] else{panic!()};id.fields[0]=NdfValue::U64(u64::MAX);}}let wire=nepl3_wire::encode(&raw,&mut budget()).map_err(err)?;assert!(portable::prepare::plan_from_value(&nepl3_wire::decode(&wire,&mut budget()).map_err(err)?,&received,profile.registry(),&mut fresh,&mut budget()).is_err());}
 let mut missing=doc.clone();missing.sources.clear();assert!(prepare::inspect(&missing,profile.registry(),&mut fresh,&mut budget()).is_err());
 for reason in [StopReason::SourceLimit,StopReason::WorkLimit,StopReason::AllocationLimit,StopReason::NodeLimit,StopReason::DepthLimit,StopReason::OutputLimit,StopReason::Cancelled]{let mut limits=budget().limits();match reason{StopReason::SourceLimit=>limits.source_bytes=0,StopReason::WorkLimit=>limits.work=0,StopReason::AllocationLimit=>limits.allocation_units=0,StopReason::NodeLimit=>limits.nodes=0,StopReason::DepthLimit=>limits.depth=0,StopReason::OutputLimit=>limits.output_bytes=0,_=>{}}let mut budget=Budget::new(limits);if reason==StopReason::Cancelled{budget.cancel();}let mut aa=SourceAdmission::default();let mut fresh=FoundationCodec::new(profile.registry(),&empty,&mut aa).map_err(err)?;assert!(matches!(prepare::inspect(&doc,profile.registry(),&mut fresh,&mut budget),Err(PreparationError::Stopped(s))if s==reason));assert_eq!(budget.poll(),Err(reason));assert_eq!(doc,unchanged);}
 let mut nested=budget();let mut aa=SourceAdmission::default();let mut fresh=FoundationCodec::new(profile.registry(),&empty,&mut aa).map_err(err)?;let actual=nested.with_depth_at_least(7,|b|prepare::inspect(&doc,profile.registry(),&mut fresh,b)).map_err(err)?;assert_eq!(actual,plan);assert_eq!(nested.current_depth(),0);assert_eq!(nested.usage().depth,operation.usage().depth+7);
 println!("actual CRLF/Unicode Article: Link/Asset before Foreign(Code then InlineMath), invalid degree/division syntax retained, document/guest independent digest, first CBOR source once, guest omission/digest/MAX and source closure negatives, 7 stops and caller7 passed");Ok(())})}

use nepl3_core::{budget::*, source::*};
use nepl3_core::{
    syntax::{Environment, EnvironmentEntry},
    value::NdfValue,
};
use nepl3_engine::{parse::*, profile::*, tree::ValidatedParseTree};
use nepl3_grammar_core::compile::package::CompiledLanguage;
use nepl3_reader::{
    model::{ProviderCall, ReadRequest, ReaderContext},
    runtime::ProviderReply,
};
use nepl3_wire::{environment::environment_digest, foundation::FoundationCodec};
fn err(v: impl std::fmt::Debug) -> String {
    format!("{v:?}")
}
fn with_input<T>(
    compiled: &Compiled,
    input: &str,
    category: &str,
    finish: impl FnOnce(
        &ValidatedParseTree<'_>,
        &ResolvedParseProfile<'_>,
        &mut Budget,
        &mut SourceAdmission,
    ) -> Result<T, String>,
) -> Result<T, String> {
    let r = &compiled.doc.registry;
    let packages: Vec<_> = std::iter::once(&compiled.doc.package)
        .chain(compiled.others.iter())
        .collect();
    // Each runtime registration identifies the actual source serving that operation.
    let implementation_for = |operation: &nepl3_core::value::OperationRef| {
        if operation.schema.package == "nepl3.doc.reader" {
            Digest::of(include_bytes!("C:/projects/NEPL3-runtime/.tmp/review-doc-prepare/source/tools/src/doc/reader.rs"))
        } else {
            Digest::of(include_bytes!(
                "C:/projects/NEPL3-runtime/.tmp/review-doc-prepare/source/crates/foundation/reader/src/builtin/provider.rs"
            ))
        }
    };
    let mut operations = Vec::new();
    for operation in packages
        .iter()
        .flat_map(|p| p.reader.providers.iter().map(|v| &v.operation))
    {
        if !operations.contains(operation) {
            operations.push(operation.clone());
        }
    }
    let providers: Vec<_> = operations
        .iter()
        .map(|operation| ProviderImplementation {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operations: vec![operation.clone()],
        })
        .collect();
    let requirements = operations
        .iter()
        .map(|operation| ProviderRequirement {
            provider: operation.name.clone(),
            revision: 1,
            implementation_digest: implementation_for(operation),
            operation: operation.clone(),
        })
        .collect();
    let mut schemas = packages
        .iter()
        .map(|p| p.schema.clone())
        .collect::<Vec<_>>();
    for schema in packages
        .iter()
        .flat_map(|p| p.payload_schemas.iter())
        .chain(
            [
                "nepl3.foundation",
                "nepl3.reader",
                "nepl3.engine",
                "nepl3.doc",
                "nepl3.doc.reader",
                "nepl3.grammar",
            ]
            .iter()
            .filter_map(|name| r.selected(name, 1)),
        )
    {
        if !schemas.contains(schema) {
            schemas.push(schema.clone());
        }
    }
    let profile = ParseProfile {
        id: "doc-prefix".into(),
        languages: packages
            .iter()
            .zip([
                ("Doc", "Article"),
                ("Math", "Expr"),
                ("Circuit", "Design"),
                ("Grammar", "Root"),
            ])
            .map(|(p, (alias, category))| {
                Ok(LanguageRegistration {
                    alias: alias.into(),
                    package: p
                        .check(r, &mut budget())
                        .and_then(|c| c.semantic_identity(&mut budget()))
                        .map_err(err)?,
                    default_category: category.into(),
                })
            })
            .collect::<Result<Vec<_>, String>>()?,
        schemas,
        head_providers: vec![],
        category_modes: vec![],
        providers: requirements,
        allowlist: operations,
        resources: vec![],
        limits: budget().limits(),
    };
    let resolved = profile
        .resolve(
            &RuntimeCatalog {
                packages: &packages,
                providers: &providers,
                resources: &[],
            },
            r,
            &mut budget(),
        )
        .map_err(err)?;
    let mut b = budget();
    let mut a = SourceAdmission::default();
    let source = SourceSnapshot::new(
        SourceId("doc-input".into()),
        0,
        "memory:doc-input".into(),
        input.as_bytes().to_vec(),
        &mut b,
    )
    .map_err(err)?;
    let tree = parse_source(&source, &resolved, category, &mut b, &mut a)?;
    let checked = tree.validate(&resolved, &mut b, &mut a).map_err(err)?;
    finish(&checked, &resolved, &mut b, &mut a)
}

fn parse_source(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    category: &str,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<nepl3_engine::recovery::ParseTree, String> {
    parse_source_as(source, resolved, "Doc", category, b, a)
}
fn parse_source_as(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    alias: &str,
    category: &str,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<nepl3_engine::recovery::ParseTree, String> {
    let r = resolved.registry();
    let foundation = r.selected("nepl3.foundation", 1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let mut contexts = Vec::new();
    for (alias, category) in [
        ("Doc", "Article"),
        ("Math", "Expr"),
        ("Circuit", "Design"),
        ("Grammar", "Root"),
    ] {
        let owner = resolved.language(alias, b).map_err(err)?;
        contexts.push(ReaderContext {
            schema: owner.schema.clone(),
            category: category.into(),
            mode: "Code".into(),
            origins: vec![],
            environment: EnvironmentEntry {
                id: 0,
                digest,
                value: value.clone(),
            },
        });
    }
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let checked = contexts
            .iter()
            .map(|raw| raw.check(&mut codec, &store, r, b).map_err(err))
            .collect::<Result<Vec<_>, String>>()?;
        let inputs = checked
            .iter()
            .zip(["Doc", "Math", "Circuit", "Grammar"])
            .map(|(context, alias)| EnvironmentInput { alias, context })
            .collect::<Vec<_>>();
        ParseEnvironmentSet::prepare(resolved, &inputs, &store, &mut codec, b)
            .map_err(|e| format!("environments: {e:?}"))?
    };
    let entry = resolved.entry(alias, Some(category), b).map_err(err)?;
    let states = ["Doc", "Math", "Circuit", "Grammar"].map(|alias| LanguageReaderState {
        alias: alias.into(),
        state: NdfValue::Unit,
    });
    let mut parser =
        ParseSession::new("doc-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read(
            ParseRequest {
                snapshot: source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    loop {
        match result.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        (if operation.schema.package == "nepl3.doc.reader" {
                            nepl3_tools::doc::reader::read
                        } else {
                            nepl3_reader::builtin::provider::read
                        })(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                result = parser
                    .resume(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            ParseOutcome::Complete { tree, cursor, .. } => {
                assert_eq!(cursor, source.text().len() as u64);
                return Ok(tree);
            }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}

