struct Compiled {
    doc: CompiledLanguage,
    others: Vec<nepl3_engine::package::LanguagePackage>,
}
fn compiled() -> Result<Compiled, String> {
    let document = nepl3_tools::bootstrap::load(
        include_bytes!("C:/projects/NEPL3-runtime/.tmp/review-doc-prepare/source/conformance/fixtures/doc/syntax.json"),
        &mut budget(),
        &mut SourceAdmission::default(),
    )
    .map_err(err)?;
    let mut doc = nepl3_tools::doc::catalog::compile(
        &document,
        "standard.doc",
        &mut budget(),
        &mut SourceAdmission::default(),
    )?;
    let mut others = Vec::new();
    for (name, seed) in [
        (
            "math",
            include_bytes!("C:/projects/NEPL3-runtime/.tmp/review-doc-prepare/source/conformance/fixtures/doc/math.json").as_slice(),
        ),
        (
            "circuit",
            include_bytes!("C:/projects/NEPL3-runtime/.tmp/review-doc-prepare/source/conformance/fixtures/doc/circuit.json").as_slice(),
        ),
        (
            "grammar",
            include_bytes!("C:/projects/NEPL3-runtime/.tmp/review-doc-prepare/source/conformance/fixtures/doc/grammar.json").as_slice(),
        ),
    ] {
        let document =
            nepl3_tools::bootstrap::load(seed, &mut budget(), &mut SourceAdmission::default())
                .map_err(err)?;
        let other = nepl3_tools::doc::catalog::compile(
            &document,
            &format!("standard.{name}"),
            &mut budget(),
            &mut SourceAdmission::default(),
        )?;
        let schema = other.package.schema.clone();
        let descriptor = other
            .registry
            .descriptor(&schema)
            .ok_or("surface descriptor")?
            .clone();
        doc.registry
            .register(schema, descriptor, &mut budget())
            .map_err(err)?;
        others.push(other.package);
    }
    doc.registry.finalize(&mut budget()).map_err(err)?;
    Ok(Compiled { doc, others })
}

