fn b()->Budget{Budget::new(Limits{work:1_000_000_000,allocation_units:1_000_000_000,output_bytes:10_000_000,source_bytes:1_000_000,nodes:1_000_000,depth:1000,diagnostics:100,events:100})}
fn registry()->Result<SchemaRegistry,String>{let mut r=SchemaRegistry::default();for d in [nepl3_core::schema::foundation::descriptor(&mut b()),nepl3_doc_core::schema::descriptor(&mut b())]{let d=d.map_err(err)?;r.register(d.reference(&mut b()).map_err(err)?,d,&mut b()).map_err(err)?;}r.finalize(&mut b()).map_err(err)?;Ok(r)}
