fn document()->DocumentSyntax{let kinds=vec![
 DocKind::Article{language:"ja".into(),title:SentenceRef(1),body:BodyRef(3)},
 DocKind::Sentence{inlines:vec![InlineRef(2)]},DocKind::Text{text:"共通".into()},
 DocKind::Body{blocks:vec![BlockRef(4)]},DocKind::Paragraph{items:vec![FlowRef(5)]},
 DocKind::Parallel{variants:vec![VariantRef(6),VariantRef(7)]},
