 DocKind::Sentence{inlines:vec![InlineRef(11),InlineRef(13),InlineRef(15)]},
 DocKind::Link{target:LinkTarget::Relative{path:"../資料.html".into(),fragment:Some("先".into())},label:InlineRef(2)},
 DocKind::Link{target:LinkTarget::External{uri:"javascript:noop()".into()},label:InlineRef(2)},
 DocKind::InlineImage{asset:asset(),alt:SentenceRef(1)},DocKind::InlineImage{asset:asset(),alt:SentenceRef(1)},
 DocKind::Anchor{id:"先".into(),label:InlineRef(2)},DocKind::Reference{target:"先".into(),label:InlineRef(2)}];
 DocumentSyntax{value:DocValue{root:DocRoot::Article(ArticleRef(0)),nodes:kinds.into_iter().map(|kind|DocNode{kind,locations:vec![],span:None,origin:None}).collect(),embeds:vec![]},sources:vec![],origins:vec![],views:vec![],source_maps:vec![]}}
fn main()->Result<(),String>{let r=registry()?;let d=document();let original=d.clone();let store=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(&r,&store,&mut a).map_err(err)?;
 let mut op=b();let plan=prepare::inspect(&d,&r,&mut c,&mut op).map_err(err)?;
 assert_eq!(plan.requirements,vec![DocRequirement::Link{node:10,target:LinkTarget::Relative{path:"../資料.html".into(),fragment:Some("先".into())}},DocRequirement::Link{node:11,target:LinkTarget::External{uri:"javascript:noop()".into()}},DocRequirement::Asset{node:12,asset:asset()},DocRequirement::Asset{node:13,asset:asset()}]);assert_eq!(d,original);
 let doc_raw=portable::to_value(&d,&r,&mut c,&mut b()).map_err(err)?;let doc_bytes=nepl3_wire::encode(&doc_raw,&mut b()).map_err(err)?;let mut digest=b"NEPL3.Doc.Prepare.Document.v1\0".to_vec();digest.extend(&doc_bytes);assert_eq!(plan.document_digest,Digest::of(&digest));
 let raw=portable::prepare::plan_to_value(&plan,&d,&r,&mut c,&mut b()).map_err(err)?;
 let bytes=nepl3_wire::encode(&raw,&mut b()).map_err(err)?;
 let empty=SourceStore::default();let mut aa=SourceAdmission::default();let mut fresh=FoundationCodec::new(&r,&empty,&mut aa).map_err(err)?;let received=portable::from_value(&nepl3_wire::decode(&doc_bytes,&mut b()).map_err(err)?,&r,&mut fresh,&mut b()).map_err(err)?;
 assert_eq!(portable::prepare::plan_from_value(&nepl3_wire::decode(&bytes,&mut b()).map_err(err)?,&received,&r,&mut fresh,&mut b()).map_err(err)?,plan);
 for mutation in 0..6{let mut bad=raw.clone();let NdfValue::Record(record)=&mut bad else{panic!()};let NdfValue::List(req)=&mut record.fields[1] else{panic!()};match mutation{0=>{req.remove(1);},1=>req.push(req[0].clone()),2=>req.swap(0,1),3=>{let NdfValue::Variant(v)=&mut req[0] else{panic!()};v.fields[0]=NdfValue::U64(u64::MAX);},4=>{let NdfValue::Variant(v)=&mut req[0] else{panic!()};v.fields[0]=NdfValue::U64(11);},_=>req.clear()}
  let packet=nepl3_wire::encode(&bad,&mut b()).map_err(err)?;let value=nepl3_wire::decode(&packet,&mut b()).map_err(err)?;assert!(portable::prepare::plan_from_value(&value,&received,&r,&mut fresh,&mut b()).is_err());}
 let mut stale=d.clone();stale.value.nodes[2].kind=DocKind::Text{text:"変更".into()};assert!(portable::prepare::plan_from_value(&raw,&stale,&r,&mut fresh,&mut b()).is_err());assert!(portable::prepare::plan_to_value(&plan,&stale,&r,&mut fresh,&mut b()).is_err());
 // Declared source bytes are identity inputs even when no position points at
 // them. Requirements alone do not make an old plan current.
 let mut sourced=d.clone();sourced.sources.push(nepl3_core::source::SourceSnapshot::new(nepl3_core::source::SourceId("extra".into()),0,"memory:extra".into(),b"original".to_vec(),&mut b()).map_err(err)?);
 let mut aa=SourceAdmission::default();let mut cc=FoundationCodec::new(&r,&empty,&mut aa).map_err(err)?;let sourced_plan=prepare::inspect(&sourced,&r,&mut cc,&mut b()).map_err(err)?;assert_eq!(sourced_plan.requirements,plan.requirements);assert_ne!(sourced_plan.document_digest,plan.document_digest);assert!(portable::prepare::plan_from_value(&raw,&sourced,&r,&mut cc,&mut b()).is_err());
 let mut missing=d.clone();missing.value.nodes[15].kind=DocKind::Reference{target:"missing-in-en".into(),label:InlineRef(2)};assert!(matches!(prepare::inspect(&missing,&r,&mut fresh,&mut b()),Err(PreparationError::Label(_))));
 let mut duplicate=d.clone();if let DocKind::Sentence{inlines}=&mut duplicate.value.nodes[9].kind{inlines.push(InlineRef(14));}assert!(matches!(prepare::inspect(&duplicate,&r,&mut fresh,&mut b()),Err(PreparationError::Label(_))));
 for reason in [StopReason::WorkLimit,StopReason::AllocationLimit,StopReason::NodeLimit,StopReason::DepthLimit,StopReason::OutputLimit,StopReason::Cancelled]{let mut l=b().limits();match reason{StopReason::WorkLimit=>l.work=0,StopReason::AllocationLimit=>l.allocation_units=0,StopReason::NodeLimit=>l.nodes=0,StopReason::DepthLimit=>l.depth=0,StopReason::OutputLimit=>l.output_bytes=0,_=>{}}let mut op=Budget::new(l);if reason==StopReason::Cancelled{op.cancel();}let mut aa=SourceAdmission::default();let mut cc=FoundationCodec::new(&r,&empty,&mut aa).map_err(err)?;assert!(matches!(prepare::inspect(&d,&r,&mut cc,&mut op),Err(PreparationError::Stopped(s)) if s==reason));assert_eq!(op.poll(),Err(reason));assert_eq!(d,original);}
 let used=op.usage().work;let mut stops=0;let mut successes=0;for cap in (0..used).step_by((used/20).max(1) as usize).chain([used]){let mut l=b().limits();l.work=cap;let mut bb=Budget::new(l);let mut aa=SourceAdmission::default();let mut cc=FoundationCodec::new(&r,&empty,&mut aa).map_err(err)?;match prepare::inspect(&d,&r,&mut cc,&mut bb){Ok(actual)=>{assert_eq!(actual,plan);successes+=1;},Err(PreparationError::Stopped(StopReason::WorkLimit))=>{stops+=1;assert_eq!(bb.poll(),Err(StopReason::WorkLimit));},e=>return Err(format!("sweep {cap}: {e:?}"))}assert!(bb.usage().work<=cap);}assert!(stops>0&&successes>0);
 println!("Parallel all variants / arena ordering / shared node once / distinct equal assets / unresolved and duplicate labels / 6 raw mutations / stale same requirements / 6 stops / Work sweep / initial CBOR and independent document digest passed");Ok(())}

